import sys

def main():
    n = int(sys.stdin.read().split()[0])
    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        best = n
        for ch in set(str(i)):
            d = ord(ch) - 48
            if d and dp[i - d] < best:
                best = dp[i - d]
        dp[i] = best + 1
    print(dp[n])

