n = int(sys.stdin.read().split()[0])
dist = {n: 0}
q = deque([n])
while q:
    x = q.popleft()
    if x == 0:
        break
    for ch in set(str(x)):
        d = int(ch)
        if d and x - d not in dist:
            dist[x - d] = dist[x] + 1
            q.append(x - d)
